//! Whole-read scores must match PMDtools 0.60 for every read of tests/data/reads_random.sam in
//! every mode of tests/data/reads_random_pmdtools.tsv (generated by tests/oracle/gen_read_fixture.py).

use std::fs::File;

use noodles_util::alignment;
use pmdshodh::model::Params;
use pmdshodh::reads::{Outcome, ReadFilters, process};
use pmdshodh::sites::{Library, Settings, Treatment};

/// PMDtools multiplies site probabilities and takes one log; pmdshodh sums logs.
/// The two agree to rounding error.
const TOLERANCE: f64 = 1e-9;

fn data(name: &str) -> String {
    format!("{}/tests/data/{name}", env!("CARGO_MANIFEST_DIR"))
}

fn settings(mode: &str) -> Settings {
    let (library, treatment) = match mode {
        "ds" | "ds_q20" | "ds_params" => (Library::DoubleStranded, Treatment::None),
        "ds_half" => (Library::DoubleStranded, Treatment::Half),
        "ds_full" => (Library::DoubleStranded, Treatment::Full),
        "ss" => (Library::SingleStranded, Treatment::None),
        "ss_half" => (Library::SingleStranded, Treatment::Half),
        "ss_full" => (Library::SingleStranded, Treatment::Full),
        other => panic!("unknown mode {other}"),
    };
    let params = if mode == "ds_params" {
        Params {
            p: 0.5,
            c: 0.02,
            pi_ancient: 0.002,
            pi_contamination: 0.003,
        }
    } else {
        Params::default()
    };
    Settings {
        library,
        treatment,
        params,
        min_baseq: if mode == "ds_q20" { 20 } else { 0 },
        pmdtools_compat: true,
    }
}

/// With --pmdtools-compat, every read matches PMDtools in every mode, including reads hit by
/// PMDtools' reference bug (docs/blackbox.md 1.6c).
#[test]
fn read_scores_match_pmdtools_0_60_in_all_modes() {
    let expected = std::fs::read_to_string(data("reads_random_pmdtools.tsv")).unwrap();
    let mut lines = expected.lines().filter(|l| !l.starts_with('#'));
    let modes: Vec<&str> = lines.next().unwrap().split('\t').skip(1).collect();
    let rows: Vec<Vec<&str>> = lines.map(|l| l.split('\t').collect()).collect();
    assert_eq!(rows.len(), 1500, "fixture row count");

    for (col, mode) in modes.iter().enumerate() {
        let s = settings(mode);
        let mut reader = alignment::io::reader::Builder::default()
            .build_from_reader(File::open(data("reads_random.sam")).unwrap())
            .unwrap();
        let header = reader.read_header().unwrap();
        let (mut n, mut worst) = (0usize, 0f64);
        for (row, record) in rows.iter().zip(reader.records(&header)) {
            let record = record.unwrap();
            assert_eq!(record.name().unwrap().to_string(), row[0], "read order");
            let want: f64 = row[col + 1].parse().unwrap();
            let got = match process(record.as_ref(), &s, &ReadFilters::default(), None) {
                Ok(Outcome::Scored { score, .. }) => score.pmds,
                other => panic!("{mode} {}: expected a score, got {other:?}", row[0]),
            };
            let diff = (got - want).abs();
            assert!(
                diff <= TOLERANCE,
                "{mode} {}: pmdshodh {got}, PMDtools {want}, diff {diff}",
                row[0]
            );
            worst = worst.max(diff);
            n += 1;
        }
        assert_eq!(n, rows.len(), "{mode}: every read compared");
        println!("{mode}: {n} reads, largest difference {worst:e}");
    }
}

/// Without --pmdtools-compat, reads PMDtools reconstructs correctly (no insertion or soft clip,
/// or neither a deletion nor '=' operations) still match exactly; affected reads may differ.
#[test]
fn default_mode_matches_pmdtools_where_its_reference_is_correct() {
    let expected = std::fs::read_to_string(data("reads_random_pmdtools.tsv")).unwrap();
    let rows: Vec<Vec<&str>> = expected
        .lines()
        .filter(|l| l.starts_with("read0"))
        .map(|l| l.split('\t').collect())
        .collect();
    let mut s = settings("ds");
    s.pmdtools_compat = false;
    let mut reader = alignment::io::reader::Builder::default()
        .build_from_reader(File::open(data("reads_random.sam")).unwrap())
        .unwrap();
    let header = reader.read_header().unwrap();
    let (mut unaffected, mut affected, mut affected_differ) = (0, 0, 0);
    for (row, record) in rows.iter().zip(reader.records(&header)) {
        let record = record.unwrap();
        let ops: Vec<_> = record.cigar().iter().map(|op| op.unwrap().kind()).collect();
        use noodles::sam::alignment::record::cigar::op::Kind;
        let gap_path = ops
            .iter()
            .any(|k| matches!(k, Kind::Insertion | Kind::SoftClip));
        let triggers = ops
            .iter()
            .any(|k| matches!(k, Kind::Deletion | Kind::SequenceMatch));
        let want: f64 = row[1].parse().unwrap();
        let Ok(Outcome::Scored { score: got, .. }) =
            process(record.as_ref(), &s, &ReadFilters::default(), None)
        else {
            panic!("{}: not scored", row[0]);
        };
        if gap_path && triggers {
            affected += 1;
            if (got.pmds - want).abs() > TOLERANCE {
                affected_differ += 1;
            }
        } else {
            unaffected += 1;
            assert!(
                (got.pmds - want).abs() <= TOLERANCE,
                "{}: {} vs PMDtools {want}",
                row[0],
                got.pmds
            );
        }
    }
    println!(
        "unaffected {unaffected} (all equal); affected {affected}, of which {affected_differ} differ"
    );
    assert!(
        affected_differ > 0,
        "fixture should exercise the PMDtools bug"
    );
}
